import{c as a,Q as t,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/troubleshooting.md","filePath":"user/reference/troubleshooting.md"}'),o={name:"user/reference/troubleshooting.md"};function s(i,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p><strong>Audience:</strong> Anyone hitting an error or unexpected behaviour in Manager.</p><p>Symptoms, likely causes, and fixes — ordered by how likely you are to hit each one.</p><blockquote><p><strong>Status:</strong> Stub — not yet written. Expect this page to grow as operators feed back real-world problems.</p></blockquote><h2 id="starting-manager" tabindex="-1">Starting Manager <a class="header-anchor" href="#starting-manager" aria-label="Permalink to &quot;Starting Manager&quot;">​</a></h2><h3 id="macos-says-mesho-manager-is-damaged-and-can-t-be-opened" tabindex="-1">macOS says meshO Manager &quot;is damaged and can&#39;t be opened&quot; <a class="header-anchor" href="#macos-says-mesho-manager-is-damaged-and-can-t-be-opened" aria-label="Permalink to &quot;macOS says meshO Manager &quot;is damaged and can&#39;t be opened&quot;&quot;">​</a></h3><p><strong>The app is not damaged.</strong> macOS shows this (or &quot;…can&#39;t be opened because it is from an unidentified developer&quot;) the first time you launch Manager because it isn&#39;t notarised by Apple yet and your browser tagged the download with a quarantine flag. <strong>Don&#39;t move it to the Bin.</strong> Open <strong>Terminal</strong> and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/meshO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Manager.app</span></span></code></pre></div><p>Then launch Manager normally from Applications. This is a one-time step. It is not caused by the browser you used (Safari, Chrome and Edge all behave the same), and on Apple Silicon Macs the &quot;damaged&quot; message is <em>not</em> cleared by right-click → Open — only the Terminal command above works. Full details, including the milder Intel-Mac path, are in <a href="./../download-and-install/#allowing-the-app-on-macos">Allowing the app on macOS</a>.</p><h2 id="connecting-hardware" tabindex="-1">Connecting hardware <a class="header-anchor" href="#connecting-hardware" aria-label="Permalink to &quot;Connecting hardware&quot;">​</a></h2><h3 id="the-sportident-station-doesn-t-appear-in-the-browser-s-device-chooser-macos" tabindex="-1">The SportIdent station doesn&#39;t appear in the browser&#39;s device chooser (macOS) <a class="header-anchor" href="#the-sportident-station-doesn-t-appear-in-the-browser-s-device-chooser-macos" aria-label="Permalink to &quot;The SportIdent station doesn&#39;t appear in the browser&#39;s device chooser (macOS)&quot;">​</a></h3><p>On a Mac, the browser&#39;s serial-device chooser comes up <strong>empty</strong> (or lists only unrelated ports) even though the station is plugged in and powered. macOS doesn&#39;t recognise SportIdent&#39;s USB product ID, so it never creates a serial port for the station — and Web Serial can only offer up real ports. Install the Silicon Labs CP210x driver once per Mac, and approve it in <strong>System Settings</strong> (the installer stalls at &quot;Installing new driver…&quot; until you do). Full steps: <a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a>.</p><p>If the chooser <em>does</em> list the station but the download controls never appear at all, that&#39;s a different problem — Web Serial needs a secure connection off the server machine. See <a href="./https-and-certificates">HTTPS and certificates</a>.</p><h2 id="reaching-the-server" tabindex="-1">Reaching the server <a class="header-anchor" href="#reaching-the-server" aria-label="Permalink to &quot;Reaching the server&quot;">​</a></h2><h3 id="a-laptop-can-t-find-the-server-by-name-—-dns-probe-finished-nxdomain" tabindex="-1">A laptop can&#39;t find the server by name — <code>DNS_PROBE_FINISHED_NXDOMAIN</code> <a class="header-anchor" href="#a-laptop-can-t-find-the-server-by-name-—-dns-probe-finished-nxdomain" aria-label="Permalink to &quot;A laptop can&#39;t find the server by name — `DNS_PROBE_FINISHED_NXDOMAIN`&quot;">​</a></h3><p>Chrome shows <strong>&quot;This site can&#39;t be reached&quot;</strong> with <code>DNS_PROBE_FINISHED_NXDOMAIN</code> for the name-based access link, while the same address opens fine in Safari, Firefox or on a phone. Chrome uses its own DNS resolver and frequently won&#39;t resolve the server&#39;s computer name, so it asks the router instead — which has no record for it.</p><p>Use the link tagged <strong>IP</strong> in <strong>Settings → Server → Access links</strong> on that laptop. This hits download and station-backup machines hardest, because those are the ones typically running Chrome for Web Serial. To use a name on them anyway, give the server a DHCP reservation and host name on the venue router, or run Firefox 151+ there — it also has Web Serial and looks names up through the operating system. Full detail: <a href="./server-addresses">Reaching the server: name or IP</a>.</p><blockquote><p>If <strong>neither</strong> the name nor the IP works from another device, it isn&#39;t this — check <strong>Allow access from other devices on the network</strong> in <strong>Settings → Server</strong>, then the server machine&#39;s firewall.</p></blockquote><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><h3 id="starting-manager-1" tabindex="-1">Starting Manager <a class="header-anchor" href="#starting-manager-1" aria-label="Permalink to &quot;Starting Manager&quot;">​</a></h3><ul><li>[ ] Manager won&#39;t start / crashes on launch</li><li>[ ] Previous version not fully uninstalled</li></ul><h3 id="connecting-hardware-1" tabindex="-1">Connecting hardware <a class="header-anchor" href="#connecting-hardware-1" aria-label="Permalink to &quot;Connecting hardware&quot;">​</a></h3><ul><li>[ ] meshO Prime isn&#39;t detected on any COM port</li><li>[ ] COM port opens but no messages arrive</li><li>[ ] Connection keeps dropping</li><li>[ ] SI reader not detected (the macOS driver case is covered above)</li></ul><h3 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h3><ul><li>[ ] Imported event shows no competitors / classes</li><li>[ ] Duplicate competitors after a re-import</li><li>[ ] Can&#39;t find a specific event in the Events list</li><li>[ ] Unexpected statuses after an import</li></ul><h3 id="during-the-event" tabindex="-1">During the event <a class="header-anchor" href="#during-the-event" aria-label="Permalink to &quot;During the event&quot;">​</a></h3><ul><li>[ ] Punches arriving but not landing on competitors</li><li>[ ] Radio punches stopped suddenly</li><li>[ ] Screens are blank or stuck</li><li>[ ] Dashboard shows alerts I don&#39;t understand</li><li>[ ] Time on a radio / SI box is wrong</li></ul><h3 id="logs-and-diagnostic-data" tabindex="-1">Logs and diagnostic data <a class="header-anchor" href="#logs-and-diagnostic-data" aria-label="Permalink to &quot;Logs and diagnostic data&quot;">​</a></h3><ul><li>[ ] Where Manager keeps its logs</li><li>[ ] How to grab a capture file for bug reports</li><li>[ ] Useful information to attach to a support request</li><li>[ ] Repairing a corrupted event — see <a href="./backup-and-restore">Backup and restore</a></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li><li><a href="./server-addresses">Reaching the server: name or IP</a></li><li><a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a></li><li><a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a></li><li><a href="./../download-and-install/">Installing meshO Manager</a></li></ul>',31)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
